from collections import defaultdict
scores = defaultdict(float)
for ranking in [['doc-a', 'doc-b'], ['doc-b', 'doc-c']]:
    for rank, doc in enumerate(ranking, start=1):
        scores[doc] += 1 / (60 + rank)
print(sorted(scores, key=lambda d: (-scores[d], d)))

def request_cost(n_in, n_out, rate_in, rate_out):
    return (n_in * rate_in + n_out * rate_out) / 1_000_000

print(request_cost(1000, 500, 2, 6))

