def chunk(tokens, size, overlap):
    windows = []
    for start in range(0, len(tokens), size - overlap):
        windows.append(tokens[start:start + size])
        if start + size >= len(tokens):
            break
    return windows

def fuse(rankings):
    scores = {}
    for ranking in rankings:
        for rank, doc in enumerate(ranking, 1):
            scores[doc] = scores.get(doc, 0) + 1 / (60 + rank)
    return sorted(scores, key=lambda doc: (-scores[doc], doc))

def recall_at_k(relevant, ranked, k):
    gold = set(relevant)
    return len(gold.intersection(ranked[:k])) / len(gold) if gold else 0.0

def reciprocal_rank(relevant, ranking):
    gold = set(relevant)
    return next((1 / i for i, doc in enumerate(ranking, 1) if doc in gold), 0.0)

def refusal_recall(answerable, refused):
    absent = [r for available, r in zip(answerable, refused) if not available]
    return sum(absent) / len(absent) if absent else 0.0
